contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, bool callWithdrawAll) public payable {
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        assert(
            countAfter == countBefore &&
            (
                reverted
                    ? balAfter == balBefore
                    : balAfter == 0
            )
        );
    }

    receive() external payable {}
}

