pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, bool callWithdrawAll) internal {
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(countAfter == countBefore &&
            (
                reverted
                    ? balAfter == balBefore
                    : balAfter == 0
            ));
    }

    function testFuzz_run(uint256 amount, bool callWithdrawAll) public {
        _run(amount, callWithdrawAll);
    }

    receive() external payable {}
}
